type SmsResult = { ok: true; messageId: string } | { ok: false; reason: "invalid_number" | "rejected" | "unavailable" };
type SmsSender = { send(to: string, text: string): Promise<SmsResult> };

const sdk = {
  down: false,
  async dispatch(msisdn: string): Promise<{ accepted: boolean; ref?: string; error?: string }> {
    if (this.down) throw new Error("ETIMEDOUT");
    return /^234\d{10}$/.test(msisdn) ? { accepted: true, ref: "V-1" } : { accepted: false, error: "BAD_MSISDN" };
  },
};

function vendorSender(vendor: typeof sdk): SmsSender {
  return {
    async send(to) {
      try {
        const response = await vendor.dispatch(to.replace(/^\+/, ""));
        if (response.accepted && response.ref) return { ok: true, messageId: response.ref };
        return { ok: false, reason: response.error === "BAD_MSISDN" ? "invalid_number" : "rejected" };
      } catch {
        return { ok: false, reason: "unavailable" };
      }
    },
  };
}

const sender = vendorSender(sdk);
const a = await sender.send("+2348031234567", "hi");
const b = await sender.send("+234803", "hi");
sdk.down = true;
const c = await sender.send("+2348031234567", "hi");
console.log(a.ok, b.ok, b.ok ? "" : b.reason, c.ok, c.ok ? "" : c.reason);

