type Result = { ok: true } | { ok: false; reason: "unavailable" | "invalid_number" };
type Sender = { send(): Promise<Result> };

function failing(times: number, reason: "unavailable" | "invalid_number"): Sender & { calls: number } {
  const s = {
    calls: 0,
    async send(): Promise<Result> {
      s.calls++;
      return s.calls <= times ? { ok: false, reason } : { ok: true };
    },
  };
  return s;
}

function withRetry(sender: Sender, attempts: number): Sender {
  return {
    async send() {
      let result = await sender.send();
      for (let i = 2; i <= attempts && !result.ok && result.reason === "unavailable"; i++) {
        result = await sender.send();
      }
      return result;
    },
  };
}

const flaky = failing(2, "unavailable");
