type Source = { price(sku: string): Promise<number> };
type Clock = { now(): number };

let calls = 0;
const slow: Source = { price: async () => (calls++, 850000) };
let time = 0;
const clock: Clock = { now: () => time };

function withCache(source: Source, ttl: number, c: Clock): Source {
  const entries = new Map<string, { value: number; expires: number }>();
  return {
    async price(sku) {
      const hit = entries.get(sku);
      if (hit && hit.expires > c.now()) return hit.value;
      const value = await source.price(sku);
      entries.set(sku, { value, expires: c.now() + ttl });
      return value;
    },
  };
}

const prices = withCache(slow, 1000, clock);
await prices.price("RICE-5KG");
await prices.price("RICE-5KG");
const before = calls;
time = 1000;
await prices.price("RICE-5KG");
console.log(before, calls);

