type User = { name: string; role: "finance" | "support" };
type Payouts = { list(): string[]; approve(id: string): string };

const payouts: Payouts = { list: () => ["PO-1", "PO-2"], approve: (id) => `approved ${id}` };

function guardedPayouts(user: User, inner: Payouts): Payouts {
  return {
    list: () => inner.list(),
    approve(id) {
      if (user.role !== "finance") throw new Error("forbidden");
      return inner.approve(id);
    },
  };
}

const support = guardedPayouts({ name: "Musa", role: "support" }, payouts);
console.log(support.list().length);
try {
  support.approve("PO-1");
} catch (error) {
  console.log((error as Error).message);
}
console.log(guardedPayouts({ name: "Ngozi", role: "finance" }, payouts).approve("PO-1"));

