type Customer = { id: string; name: string; email: string };

class MemoryCustomerRepository {
  readonly #rows = new Map<string, Customer>();

  get count(): number {
    return this.#rows.size;
  }

  async save(customer: Customer): Promise<void> {
    this.#rows.set(customer.id, { ...customer, email: customer.email.toLowerCase() });
  }

  async findByEmail(email: string): Promise<Customer | undefined> {
    const wanted = email.toLowerCase();
    return [...this.#rows.values()].find((c) => c.email === wanted);
  }
}

const repo = new MemoryCustomerRepository();
await repo.save({ id: "C1", name: "Ada", email: "Ada@Shop.ng" });
await repo.save({ id: "C1", name: "Ada Obi", email: "ada@shop.ng" });
console.log((await repo.findByEmail("ADA@SHOP.NG"))?.name);
console.log(repo.count);
console.log(await repo.findByEmail("nobody@shop.ng"));

